<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility\ConsentPurposeVisibilityService;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway\ConsentPurposeReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ConsentPurposeRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ConsentPurposeVisibilityService $visibility,
        private readonly ConsentPurposeReadGateway $reader
    ) {
    }

    public function allowRetrieve(?ConsentPurposeRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Consent purpose");
        $span = $this->startSpan("Check allow of retrieve usecase for Consent purpose");
        try {
            $result = $this->dispatcher->dispatch(new ConsentPurposeRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?ConsentPurposeRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Consent purpose");
        $span = $this->startSpan("Check hidden fields usecase for Consent purpose");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): ConsentPurposeRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Consent purpose");
        $span = $this->startSpan("Run retrieve usecase for Consent purpose");
        try {
            $ref = new ConsentPurposeRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Consent purpose');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ConsentPurposeRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
